def transform(grid):
    h,w=len(grid),len(grid[0]); bg=max(set(v for row in grid for v in row),key=lambda v:sum(row.count(v) for row in grid))
    out=[[bg]*w for _ in range(h)]; seen=set()
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==bg or (r,c) in seen: continue
        stack=[(r,c)];seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop();cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx));stack.append((yy,xx))
        if len(cells)<4: continue
        y0=min(y for y,x in cells);y1=max(y for y,x in cells);x0=min(x for y,x in cells);x1=max(x for y,x in cells)
        area=(y1-y0+1)*(x1-x0+1)
