from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(x for row in grid for x in row)
    dividers = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            dividers.append((freq[row[0]], 'row', r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            dividers.append((freq[grid[0][c]], 'col', c))
    _, axis, k = min(dividers)
    if axis == 'row':
        a, b = grid[:k], grid[k + 1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]
    ca = Counter(x for row in a for x in row)
    cb = Counter(x for row in b for x in row)
    shared = set(ca) & set(cb)
    color = max(shared, key=lambda x: min(ca[x], cb[x]))
    return [[3 if a[r][c] == color and b[r][c] == color else color
             for c in range(min(len(a[r]), len(b[r])))] for r in range(len(a))]


